<script setup>
import {computed, ref, watch, onBeforeUnmount} from 'vue'
import {Sidebar,SidebarHeader,SidebarContent,SidebarFooter,SidebarGroup,SidebarGroupLabel,SidebarMenu,SidebarMenuItem,SidebarMenuButton,SidebarMenuSub,SidebarMenuSubItem,SidebarMenuSubButton,useSidebar} from '@/components/ui/sidebar'
import {Collapsible,CollapsibleContent,CollapsibleTrigger} from '@/components/ui/collapsible'
import {ChevronRightIcon,BoxesIcon} from '@lucide/vue'
import ConsoleIcon from './ConsoleIcon.vue'
import {availableGroups, selectedNavigation, navigationLeaves, navigationOpenKeys, extensionPlugins} from './navigation.js'
const props=defineProps({plugins:{type:Array,default:()=>[]},workspace:Object,home:Boolean,admin:Boolean})
const emit=defineEmits(['open','home','platform'])
const {setOpenMobile,state,isMobile}=useSidebar()
const groups=computed(()=>availableGroups(props.plugins))
const selected=computed(()=>props.home?'home':selectedNavigation(props.workspace?.plugin?.name,props.workspace?.hash))
const expanded=ref([])
watch(()=>[selected.value,groups.value],([key])=>{expanded.value=navigationOpenKeys(key,groups.value)},{immediate:true})
const extras=computed(()=>extensionPlugins(props.plugins))
function select(key){setOpenMobile(false);if(key==='home'){emit('home');return}const item=navigationLeaves(groups.value).find(i=>i.id===key);if(item)emit('open',item);else if(['apps','resources','mcp','plugins'].includes(key))emit('platform',key);else{const p=extras.value.find(p=>p.name===key);if(p)emit('open',{plugin:p.name,hash:'#/'})}}

import {DropdownMenu,DropdownMenuContent,DropdownMenuItem,DropdownMenuLabel,DropdownMenuSeparator,DropdownMenuTrigger} from '../shared/shadcn-ui.js'
</script>
<template><Sidebar collapsible="icon" aria-label="主导航" class="[&_[data-sidebar=menu-button]]:h-10 [&_[data-sidebar=menu-button]]:text-sm [&_[data-sidebar=menu-button]>svg]:size-5 group-data-[collapsible=icon]:[&_[data-sidebar=menu-button]>svg]:size-4 [&_[data-sidebar=menu-sub-button]]:h-9 [&_[data-sidebar=menu-sub-button]]:text-sm [&_[data-sidebar=menu-sub]]:gap-1 [&_[data-sidebar=group-label]]:text-[13px] [&_[data-sidebar=group-label]]:font-medium [&_[data-sidebar=group-label]]:text-muted-foreground">
 <SidebarHeader class="h-14 justify-center border-b"><SidebarMenu><SidebarMenuItem><SidebarMenuButton size="lg" tooltip="个人工作台" aria-label="个人工作台" @click="select('home')"><div class="flex size-8 items-center justify-center rounded-lg bg-primary text-primary-foreground"><BoxesIcon class="size-4"/></div><span class="truncate font-semibold group-data-[collapsible=icon]:hidden">DevOps 控制台</span></SidebarMenuButton></SidebarMenuItem></SidebarMenu></SidebarHeader>
 <SidebarContent><SidebarGroup><SidebarMenu><SidebarMenuItem><SidebarMenuButton :is-active="selected==='home'" tooltip="个人工作台" aria-label="个人工作台" @click="select('home')"><ConsoleIcon name="user"/><span>个人工作台</span></SidebarMenuButton></SidebarMenuItem></SidebarMenu></SidebarGroup>
 <SidebarGroup v-for="group in groups" :key="group.id" class="py-0"><DropdownMenu v-if="state==='collapsed'&&!isMobile"><SidebarMenu><SidebarMenuItem><DropdownMenuTrigger as-child><SidebarMenuButton :is-active="navigationLeaves([group]).some(item=>item.id===selected)" :tooltip="group.label" :aria-label="group.label"><ConsoleIcon :name="group.icon"/><span>{{group.label}}</span></SidebarMenuButton></DropdownMenuTrigger><DropdownMenuContent side="right" align="start" class="min-w-48"><DropdownMenuLabel>{{group.label}}</DropdownMenuLabel><template v-for="item in group.items" :key="item.id"><template v-if="item.items"><DropdownMenuSeparator/><DropdownMenuLabel class="text-xs text-muted-foreground">{{item.label}}</DropdownMenuLabel><DropdownMenuItem v-for="child in item.items" :key="child.id" @select="select(child.id)">{{child.label}}</DropdownMenuItem></template><DropdownMenuItem v-else @select="select(item.id)">{{item.label}}</DropdownMenuItem></template></DropdownMenuContent></SidebarMenuItem></SidebarMenu></DropdownMenu><Collapsible v-else :open="expanded.includes(group.id)" class="group/collapsible" @update:open="v=>{expanded=v?[...expanded,group.id]:expanded.filter(x=>x!==group.id)}"><SidebarMenu><SidebarMenuItem><CollapsibleTrigger as-child><SidebarMenuButton :tooltip="group.label" :aria-label="group.label"><ConsoleIcon :name="group.icon"/><span>{{group.label}}</span><ChevronRightIcon class="ml-auto size-4 transition-transform group-data-[state=open]/collapsible:rotate-90"/></SidebarMenuButton></CollapsibleTrigger><CollapsibleContent><SidebarMenuSub><template v-for="item in group.items" :key="item.id"><template v-if="item.items"><SidebarMenuSubItem><SidebarGroupLabel class="h-8 px-2">{{item.label}}</SidebarGroupLabel></SidebarMenuSubItem><SidebarMenuSubItem v-for="child in item.items" :key="child.id"><SidebarMenuSubButton as="button" :is-active="selected===child.id" @click="select(child.id)"><span>{{child.label}}</span></SidebarMenuSubButton></SidebarMenuSubItem></template><SidebarMenuSubItem v-else><SidebarMenuSubButton as="button" :is-active="selected===item.id" @click="select(item.id)"><span>{{item.label}}</span></SidebarMenuSubButton></SidebarMenuSubItem></template></SidebarMenuSub></CollapsibleContent></SidebarMenuItem></SidebarMenu></Collapsible></SidebarGroup>
 <SidebarGroup v-if="extras.length"><SidebarGroupLabel>扩展工具</SidebarGroupLabel><SidebarMenu><SidebarMenuItem v-for="plugin in extras" :key="plugin.name"><SidebarMenuButton :tooltip="plugin.display||plugin.name" :aria-label="plugin.display||plugin.name" @click="select(plugin.name)"><ConsoleIcon name="plugins"/><span>{{plugin.display||plugin.name}}</span></SidebarMenuButton></SidebarMenuItem></SidebarMenu></SidebarGroup>
 </SidebarContent><SidebarFooter class="border-t"><SidebarMenu><SidebarMenuItem v-for="entry in [{id:'apps',label:'应用中心',icon:'apps'},{id:'resources',label:'资源中心',icon:'resources'},...(plugins.some(p=>p.name==='devtools')?[{id:'mcp',label:'MCP 与集成',icon:'devtools'}]:[]),...(admin?[{id:'plugins',label:'插件管理',icon:'settings'}]:[])]" :key="entry.id"><SidebarMenuButton :is-active="selected===entry.id" :tooltip="entry.label" :aria-label="entry.label" @click="select(entry.id)"><ConsoleIcon :name="entry.icon"/><span>{{entry.label}}</span></SidebarMenuButton></SidebarMenuItem></SidebarMenu></SidebarFooter>
 </Sidebar></template>
